        difficulty = "hard",
    },
    [245] = {
        achievementId = 245,
        name = "That Takes Class",
        category = "PvP",
        sourceType = "Achievement",
        source = "That Takes Class",
        acquisition = "Difficulty: Medium - Participate in multiple player matches for kills, class criteria or race criteria.\n\n1. Track the achievement and expand its class checklist. Current criteria include Death Knight, Demon Hunter, Druid, Evoker, Hunter, Mage, Monk, Paladin, Priest, Rogue, Shaman, Warlock and Warrior.\n\n2. Play player battlegrounds and help defeat enemy players of the missing classes. Aim to land the killing blow on an eligible opponent, as the description requests, then inspect whether that class was checked off.\n\n3. Repeat across matches for the classes still missing. Killing creatures, attacking a training dummy or duelling a friendly class does not replace PvP kill credit. If a class fails to credit despite a recorded killing blow, note the opponent and match for a bug report.",
        stepCount = 3,
        waypoints = {},
        tips = "Comments report shared honorable-kill credit, but the route does not depend on it. The old Evoker-credit complaints describe a specific Dragonflight bug; they are not evidence that the achievement was permanently retired.",
        sources = {
            "https://www.wowhead.com/achievement=245#comments:id=406946",
            "https://www.wowhead.com/achievement=245#comments:id=598358",
            "https://www.wowhead.com/achievement=245#comments:id=5507253",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=245",
        sourceURL = "https://www.wowhead.com/achievement=245#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Participate in multiple player matches for kills, class criteria or race criteria.",
        difficulty = "medium",
    },
    [246] = {
        achievementId = 246,
        name = "Know Thy Enemy",
        category = "PvP",
        sourceType = "Achievement",
        source = "Know Thy Enemy",
        acquisition = "Difficulty: Medium - Participate in multiple player matches for kills, class criteria or race criteria.\n\n1. On the opposing faction, track this achievement and expand its race checklist. The current Horde list is: Pandaren, Goblin, Tauren, Undead, Highmountain Tauren, Blood Elf, Orc, Troll, Nightborne and Horde Dracthyr.\n\n2. Join player battlegrounds and participate in killing opponents of the races you still need. Aim for eligible honorable killing blows, then check the criterion after the kill instead of assuming every visually similar race is the same entry.\n\n3. Continue across matches until each listed race has credit. World PvP can provide a rare missing race too, but friendly duels and a player of your own faction do not satisfy this enemy-race route.",
        stepCount = 3,
        waypoints = {},
        tips = "The live checklist is authoritative if criteria change. Old comments predate allied races and Dracthyr; do not stop after only the original races.",
        sources = { "https://www.wowhead.com/achievement=1005#comments:id=408643" },
        wowheadUrl = "https://www.wowhead.com/achievement=246",
        sourceURL = "https://www.wowhead.com/achievement=246#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Participate in multiple player matches for kills, class criteria or race criteria.",
        difficulty = "medium",
    },
    [247] = {
        achievementId = 247,
        name = "Make Love, Not Warcraft",
        category = "PvP",
        sourceType = "Achievement",
        source = "Make Love, Not Warcraft",
        acquisition = "Difficulty: Easy - One player kill, one ordinary duel or one correctly timed corpse emote is enough.\n\n1. Find an opposing-faction player who is about to die, either in a player battleground or in the world. Have /hug ready on an action macro or in chat.\n\n2. Target the player's CORPSE immediately after death and use /hug before that player releases their spirit. A Spirit of Redemption is not the corpse required for this step.\n\n3. Check for achievement credit. You do not need the killing blow, an honorable kill, or even to have attacked the player; the important part is targeting the dead enemy before release.",
        stepCount = 3,
        waypoints = {},
        tips = "A cooperative opposite-faction friend can wait before releasing to give you time. Merely hugging a living enemy, their released bones or a spirit form is not the described action.",
        sources = {
            "https://www.wowhead.com/achievement=247#comments:id=334259",
            "https://www.wowhead.com/achievement=247#comments:id=416365",
            "https://www.wowhead.com/achievement=247#comments:id=488897",
            "https://www.wowhead.com/achievement=247#comments:id=1224611",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=247",
        sourceURL = "https://www.wowhead.com/achievement=247#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "One player kill, one ordinary duel or one correctly timed corpse emote is enough.",
        difficulty = "easy",
    },
    [388] = {
        achievementId = 388,
        name = "City Defender",
        category = "PvP",
        sourceType = "Achievement",
        source = "City Defender",
        acquisition = "Difficulty: Medium - Arrange compatible PvP flags and phases, travel between cities and repeat player kills.\n\n1. Travel to one of your own faction's capital cities; Stormwind is the mapped example. Enable PvP. Keep BOTH yourself and the enemy player inside the city boundary: replies correct older claims that the victim can stand outside it. Check the location text before fighting near a gate.\n\n2. Help kill enemy players who enter. Deal damage yourself or participate with the defending group. Guards and other NPCs do not count; the requirement is 50 player deaths.\n\n3. Stay inside the city boundary while earning credit, and recheck the achievement counter after a kill. The kills are cumulative and need not happen during one invasion or one day.\n\n4. For a coordinated route, bring a willing opposite-faction friend and another character who can resurrect that friend. Put everyone in the same phase, kill the volunteer inside the city, resurrect them and repeat after they accept. A 2026 report uses the mapped Stormwind entrance tower near 71, 95. Check that the first kill advances the counter before repeating; low-level volunteers can count too.",
        stepCount = 4,
        waypoints = { { mapID = 84, x = 0.71, y = 0.95, step = 1, label = "Stormwind - example city boundary; verify location text" } },
        tips = "An honorable kill or personal killing blow is not required. The opposite-faction player must be attackable, so check their PvP flag and matching War Mode/phase. Holiday visitors are another opportunity. Faction-transfer and double-credit bugs are not relied on.",
        sources = {
            "https://www.wowhead.com/achievement=388#comments:id=892121",
            "https://www.wowhead.com/achievement=1006#comments:id=892120",
            "https://www.wowhead.com/comment/show-replies?id=892121",
            "https://www.wowhead.com/comment/show-replies?id=892120",
            "https://www.wowhead.com/achievement=1006#comments:id=5388173",
            "https://www.wowhead.com/achievement=388#comments:id=6374092",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=388",
        sourceURL = "https://www.wowhead.com/achievement=388#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Arrange compatible PvP flags and phases, travel between cities and repeat player kills.",
        difficulty = "medium",
    },
    [397] = {
        achievementId = 397,
        name = "Step Into The Arena",
        category = "PvP",
        sourceType = "Achievement",
        source = "Step Into The Arena",
        acquisition = "Difficulty: Medium - Win a rated arena match or keep queuing for the missing arena maps.\n\n1. Reach the current requirements for rated arenas and find a partner for 2v2, or two partners for 3v3. Form the appropriately sized group and open the Rated PvP panel.\n\n2. Choose the matching RATED arena bracket and win completed matches. Skirmishes and Training Grounds are unrated. A March 2026 reply confirms that even a 6/6 Solo Shuffle match did not advance this older arena-win counter, so use rated 2v2 or 3v3.\n\n3. Keep using a qualifying bracket until the achievement records 1 win. Check the achievement after the result screen.",
        stepCount = 3,
        waypoints = {},
        tips = "These names refer to cumulative arena-win milestones. They do not require playing the original Merciless, Vengeful or Brutal season.",
        sources = { "https://www.wowhead.com/achievement=876#comments", "https://www.wowhead.com/comment/show-replies?id=6272472" },
        wowheadUrl = "https://www.wowhead.com/achievement=397",
        sourceURL = "https://www.wowhead.com/achievement=397#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Win a rated arena match or keep queuing for the missing arena maps.",
        difficulty = "medium",
    },
    [398] = {
        achievementId = 398,
        name = "Mercilessly Dedicated",
        category = "PvP",
        sourceType = "Achievement",
        source = "Mercilessly Dedicated",
        acquisition = "Difficulty: Hard - Accumulate many rated 2v2 or 3v3 victories; losses do not advance the counter.\n\n1. Reach the current requirements for rated arenas and find a partner for 2v2, or two partners for 3v3. Form the appropriately sized group and open the Rated PvP panel.\n\n2. Choose the matching RATED arena bracket and win completed matches. Skirmishes and Training Grounds are unrated. A March 2026 reply confirms that even a 6/6 Solo Shuffle match did not advance this older arena-win counter, so use rated 2v2 or 3v3.\n\n3. Keep using a qualifying bracket until the achievement records 100 wins. Losses slow progress but do not remove accumulated wins, and the earlier win milestones are included rather than requiring a fresh set of wins.",
        stepCount = 3,
        waypoints = {},
        tips = "These names refer to cumulative arena-win milestones. They do not require playing the original Merciless, Vengeful or Brutal season.",
        sources = { "https://www.wowhead.com/achievement=876#comments", "https://www.wowhead.com/comment/show-replies?id=6272472" },
        wowheadUrl = "https://www.wowhead.com/achievement=398",
        sourceURL = "https://www.wowhead.com/achievement=398#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Accumulate many rated 2v2 or 3v3 victories; losses do not advance the counter.",
        difficulty = "hard",
    },
    [399] = {
        achievementId = 399,
        name = "Just the Two of Us: 1550",
        category = "PvP",
        sourceType = "Achievement",
        source = "Just the Two of Us: 1550",
        acquisition = "Difficulty: Medium - Build personal rating in the specified active rated bracket.\n\n1. Form a group of 2 players and enter the RATED 2v2 arena queue from the Rated PvP panel. A Solo Shuffle rating, rated battleground rating or unrated skirmish win is not this bracket's personal rating.\n\n2. Play completed matches and raise YOUR personal rating in that bracket to at least 1550. Inspect your character's rating after the result screen; a teammate already being above the threshold does not grant you their rating.\n\n3. Keep playing through wins and losses until your own rating reaches the target, then check the achievement. No exact equality is required: crossing above 1550 is enough. Old arena-team purchase and team-rating instructions are obsolete.",
        stepCount = 3,
        waypoints = {},
        tips = "This is a rating milestone, not a promise that a fixed number of wins will achieve it. Matchmaking rating and personal rating are different values; read the rated panel's personal bracket rating.",
        sources = {
