    [408] = {
        achievementId = 408,
        name = "Hot Streak",
        category = "PvP",
        sourceType = "Achievement",
        source = "Hot Streak",
        acquisition = "Difficulty: Hard - Win ten consecutive rated arena matches, meeting the rating requirement where specified.\n\n1. Form a 2v2 or 3v3 rated arena group and track this achievement. Use actual rated arena matches; skirmishes and Solo Shuffle are not substitutes confirmed by these comment threads.\n\n2. Win ten ranked arena matches in a row. The matches need not all be played in one sitting; stopping for the day does not itself break a winning streak.\n\n3. After each result, check the streak counter. A loss or draw can break the run; changing to another bracket and losing there is not a safe way to preserve progress. Continue only with teammates ready for another match.",
        stepCount = 3,
        waypoints = {},
        tips = "Do not reuse the removed 5v5 bracket from early comments. Old suggestions to exploit forfeits, disconnects or team resets are unnecessary and unreliable.",
        sources = {
            "https://www.wowhead.com/achievement=408#comments:id=564850",
