    [545] = {
        achievementId = 545,
        name = "Shave and a Haircut",
        category = "Other",
        sourceType = "Achievement",
        source = "Shave and a Haircut",
        acquisition = "Difficulty: Easy - Buy inexpensive vendor items or make one simple customization change.\n\n1. Visit a Retail barbershop. Alliance can use the shop behind Stormwind's Trade District Auction House (61.4, 64.6); Horde can use the shop above Orgrimmar's Valley of Strength (40.8, 60.8). Look for the striped barber pole.\n\n2. Click an empty barber CHAIR to open customization. Choose a different available hairstyle or hair colour so there is an actual change to apply.\n\n3. Confirm the changes, then check achievement credit. Closing the preview without applying does not complete the visit. If you are a Worgen, customize the Worgen form if a human-form change fails to credit.",
        stepCount = 3,
        waypoints = {
            { mapID = 84, x = 0.614, y = 0.6459999999999999, step = 1, label = "Stormwind barbershop - click the chair" },
            { mapID = 85, x = 0.408, y = 0.608, step = 1, label = "Orgrimmar barbershop - above Valley of Strength" },
        },
        tips = "The old level-based gold prices and temporary free-haircut exploits in comments are obsolete. Use the current barbershop's confirmation button.",
        sources = {
            "https://www.wowhead.com/achievement=545#comments:id=566816",
            "https://www.wowhead.com/achievement=545#comments:id=1247630",
