    [603] = {
        achievementId = 603,
        name = "Wrath of the Horde",
        category = "PvP",
        sourceType = "Achievement",
        source = "Wrath of the Horde",
        acquisition = "Difficulty: Medium - Arrange compatible PvP flags and phases, travel between cities and repeat player kills.\n\n1. On a Horde character, track all four city criteria: Stormwind, Ironforge, Darnassus and Exodar. You need five Alliance player kills credited in EACH city, not five total and not the city leaders.\n\n2. Find a willing opposite-faction partner or enemy players in the city. Both characters must be able to see and attack one another in the same phase/PvP setting. Position inside the named city's boundary before the kill; a nearby starting zone is not the city criterion.\n\n3. Complete five kills in Stormwind and five in Ironforge. A quiet interior and a partner who can resurrect can reduce guard interruptions. Recheck each city after its fifth kill rather than assuming a single visible check proves the whole achievement.\n\n4. For Darnassus, visit Zidormi in Darkshore (48.8, 24.5) and select the past before the burning. Both characters must use the same phase. Enter Darnassus and finish its five kills; proceed through Rut'theran's Azuremyst connection to reach Exodar for its five kills.\n\n5. Verify all four counters. Comments confirm low-level players and repeated kills of the same player can count, so this is not an honorable-kill requirement. Use a partner rather than depending on the old rapid Alt-F4 character-switch trick.",
        stepCount = 5,
        waypoints = {
            { mapID = 84, x = 0.71, y = 0.95, step = 3, label = "Stormwind entrance tower - verify city boundary" },
            { mapID = 87, x = 0.25, y = 0.11, step = 3, label = "Ironforge outer neighbourhood - arrange a safe interior" },
            { mapID = 62, x = 0.488, y = 0.245, step = 4, label = "Zidormi - return Darkshore to the past" },
            { mapID = 89, x = 0.43, y = 0.32, step = 4, label = "Darnassus - city kill search area" },
            { mapID = 103, x = 0.5, y = 0.5, step = 4, label = "Exodar - city kill search area" },
        },
        tips = "Darnassus remains accessible through Retail's past phase. The 2025 comment explicitly calls out this phase switch; older obsolete boat instructions are replaced. War Mode is not the only PvP flag, but participants must use compatible settings and phases.",
        sources = {
            "https://www.wowhead.com/achievement=603#comments:id=1579426",
            "https://www.wowhead.com/achievement=603#comments:id=5466704",
            "https://www.wowhead.com/achievement=603#comments:id=6043220",
            "https://www.wowhead.com/npc=141489/zidormi",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=603",
        sourceURL = "https://www.wowhead.com/achievement=603#comments",
        reviewedAt = "2026-11-04",
