    [699] = {
        achievementId = 699,
        name = "World Wide Winner",
        category = "PvP",
        sourceType = "Achievement",
        source = "World Wide Winner",
        acquisition = "Difficulty: Medium - Win a rated arena match or keep queuing for the missing arena maps.\n\n1. Track the achievement's six arena criteria: Blade's Edge, Nagrand, Dalaran Sewers, Ruins of Lordaeron, Tol'Viron and Tiger's Peak.\n\n2. Form a group for rated 2v2 or 3v3 and queue through Rated PvP. The arena is assigned by matchmaking; travelling to a similarly named outdoor ring does not select the rated map.\n\n3. Win on each required arena as it appears. Repeat queued matches for missing maps and check the criterion after a win. You cannot replace a missing map with extra wins on another map.",
        stepCount = 3,
        waypoints = {},
        tips = "Ring of Valor was replaced in the criterion list by Tiger's Peak. Do not follow older instructions to wait for Ring of Valor to return or walk through an outdoor arena entrance.",
        sources = { "https://www.wowhead.com/achievement=699#comments:id=1878013" },
        wowheadUrl = "https://www.wowhead.com/achievement=699",
        sourceURL = "https://www.wowhead.com/achievement=699#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Win a rated arena match or keep queuing for the missing arena maps.",
        difficulty = "medium",
    },
    [700] = {
        achievementId = 700,
        name = "Freedom of the Horde",
        category = "PvP",
        sourceType = "Achievement",
        source = "Freedom of the Horde",
        acquisition = "Difficulty: Medium - Earn PvP currency or complete the tower-capture route and obtain the correct reward.\n\n1. On a Horde character, inspect the old PvP vendor First Sergeant Hola'mahi. Find the ORIGINAL Insignia of the Horde that matches your class, rather than a modern PvP medallion with a similar effect.\n\n2. Check the item tooltip's class restriction and current Honor price, then buy the eligible insignia. Keep it in your bags and check achievement credit; if the award is delayed, relog once with the item still owned.\n\n3. For an alternative without an Honor purchase, visit Battlecryer Blackeye in Thrallmar (55.8, 39.0) in OUTLAND Hellfire Peninsula. Take the ORIGINAL Hellfire Fortifications quest (13409), whose reward includes Insignia of the Horde. Its later daily version does not award that insignia. If it is unavailable, finish the initial Thrallmar chain through Felspark Ravine and Forward Base: Reaver's Fall.\n\n4. Enable PvP and stand on the ground, out of stealth, inside each fortification: the Overlook around 40, 48, the Stadium around 35, 50 and Broken Hill around 40, 56. Wait for its capture bar to reach your faction and for the quest objective to tick. A fort already owned by your faction cannot be captured again until the opposition takes it or makes it neutral; arrange a willing opposite-faction helper if needed. Both characters must use the same phase/War Mode setting.\n\n5. Return to the quest giver, choose the insignia and keep it in your bags. Relog once if the achievement does not immediately appear. An October 2026 reply confirms the Hellfire quest route still grants this Legacy achievement; no enemy-player kill is required for an uncontested tower capture.\n\n6. If the original quest is already completed and you lack an eligible vendor insignia, obtain a Vicious Gladiator's medallion from Argaloth in Baradin Hold. This is random loot and may need more than one reset; the raid is entered only while your faction controls Tol Barad.",
        stepCount = 6,
        waypoints = {
            { mapID = 85, x = 0.382, y = 0.726, step = 1, label = "First Sergeant Hola'mahi - original class insignias" },
            {
                mapID = 100,
                x = 0.5579999999999999,
                y = 0.39,
                step = 3,
                label = "Battlecryer Blackeye in Thrallmar (55.8, 39.0) - original insignia quest",
            },
            { mapID = 100, x = 0.4, y = 0.48, step = 4, label = "The Overlook - PvP capture area" },
            { mapID = 100, x = 0.35, y = 0.5, step = 4, label = "The Stadium - PvP capture area" },
            { mapID = 100, x = 0.4, y = 0.56, step = 4, label = "Broken Hill - PvP capture area" },
            {
                mapID = 100,
                x = 0.5579999999999999,
                y = 0.39,
                step = 5,
                label = "Hellfire Fortifications - choose and keep the insignia",
            },
            { mapID = 244, x = 0.46, y = 0.488, step = 6, label = "Baradin Hold - alternative Argaloth medallion loot" },
        },
        tips = "Use the original insignia or a specifically confirmed medallion. Heirloom insignias and every later season's medallion do not necessarily qualify. Tower ownership can require waiting or help from the opposite faction; enable the PvP flag before entering its capture area if the bar does not appear.",
        sources = {
