        difficulty = "medium",
    },
    [869] = {
        achievementId = 869,
        name = "50000 Honorable Kills",
        category = "PvP",
        sourceType = "Achievement",
        source = "50000 Honorable Kills",
        acquisition = "Difficulty: Hard - These large honorable-kill totals take substantial cumulative PvP play.\n\n1. Queue for player battlegrounds or epic battlegrounds and track this achievement. World PvP can also count when the opponent is an eligible honorable kill.\n\n2. Stay within the fighting group and contribute damage or healing when enemy players die. Shared honorable kills count; you do not need the personal killing blow. Very low-level opponents and ordinary duels are not a dependable source of honorable kills.\n\n3. Continue until the achievement counter reaches 50000. The total is cumulative, so deaths or losing a battleground do not erase previously credited kills. Check the achievement itself rather than equating earned Honor currency with kill count.",
        stepCount = 3,
        waypoints = {},
        tips = "The current Retail pages mark the 100-and-higher milestones as account-wide progress. Older comments that call all milestones through 10,000 character-only are outdated. A single character's Statistics counter can differ from this combined achievement counter.",
        sources = {
            "https://www.wowhead.com/achievement=869",
            "https://www.wowhead.com/achievement=239#comments:id=1651744",
