    [875] = {
        achievementId = 875,
        name = "Vengefully Dedicated",
        category = "PvP",
        sourceType = "Achievement",
        source = "Vengefully Dedicated",
        acquisition = "Difficulty: Hard - Accumulate many rated 2v2 or 3v3 victories; losses do not advance the counter.\n\n1. Reach the current requirements for rated arenas and find a partner for 2v2, or two partners for 3v3. Form the appropriately sized group and open the Rated PvP panel.\n\n2. Choose the matching RATED arena bracket and win completed matches. Skirmishes and Training Grounds are unrated. A March 2026 reply confirms that even a 6/6 Solo Shuffle match did not advance this older arena-win counter, so use rated 2v2 or 3v3.\n\n3. Keep using a qualifying bracket until the achievement records 200 wins. Losses slow progress but do not remove accumulated wins, and the earlier win milestones are included rather than requiring a fresh set of wins.",
        stepCount = 3,
        waypoints = {},
        tips = "These names refer to cumulative arena-win milestones. They do not require playing the original Merciless, Vengeful or Brutal season.",
        sources = { "https://www.wowhead.com/achievement=876#comments", "https://www.wowhead.com/comment/show-replies?id=6272472" },
        wowheadUrl = "https://www.wowhead.com/achievement=875",
        sourceURL = "https://www.wowhead.com/achievement=875#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Accumulate many rated 2v2 or 3v3 victories; losses do not advance the counter.",
        difficulty = "hard",
    },
    [876] = {
        achievementId = 876,
        name = "Brutally Dedicated",
        category = "PvP",
        sourceType = "Achievement",
        source = "Brutally Dedicated",
        acquisition = "Difficulty: Hard - Accumulate many rated 2v2 or 3v3 victories; losses do not advance the counter.\n\n1. Reach the current requirements for rated arenas and find a partner for 2v2, or two partners for 3v3. Form the appropriately sized group and open the Rated PvP panel.\n\n2. Choose the matching RATED arena bracket and win completed matches. Skirmishes and Training Grounds are unrated. A March 2026 reply confirms that even a 6/6 Solo Shuffle match did not advance this older arena-win counter, so use rated 2v2 or 3v3.\n\n3. Keep using a qualifying bracket until the achievement records 300 wins. Losses slow progress but do not remove accumulated wins, and the earlier win milestones are included rather than requiring a fresh set of wins.",
        stepCount = 3,
        waypoints = {},
        tips = "The reward is the Tabard of Brute Force. Check the achievement counter and reward mail; old comments about character-only tabard appearances predate account-wide transmog.",
        sources = { "https://www.wowhead.com/achievement=876#comments", "https://www.wowhead.com/comment/show-replies?id=6272472" },
        wowheadUrl = "https://www.wowhead.com/achievement=876",
