    [889] = {
        achievementId = 889,
        name = "Fast and Furious",
        category = "Other",
        sourceType = "Achievement",
        source = "Fast and Furious",
        acquisition = "Difficulty: Easy - Ordinary early levelling automatically completes this milestone.\n\n1. Level a permanent Retail character to 10. Retail automatically teaches Journeyman Riding at this threshold; the old trainer purchase and gold cost are obsolete.\n\n2. Open the Mount Journal and summon a learned mount. For Expert Riding, use an area where flight is allowed; restricted zones and introductory scenarios can prevent flight without removing the riding skill.\n\n3. Check the achievement after reaching the required level. Buying another mount or visiting an old riding trainer is unnecessary when the skill is already learned.",
        stepCount = 3,
        waypoints = {},
        tips = "The War Within changed the older comment's thresholds: Journeyman is now learned at 10 and Expert at 20. Apprentice and Artisan Riding were removed, so their retired achievements are excluded. A new neutral Pandaren must finish choosing a faction before riding unlocks.",
        sources = {
            "https://www.wowhead.com/achievement=889#comments:id=5650305",
