    [941] = {
        achievementId = 941,
        name = "Hemet Nesingwary: The Collected Quests",
        category = "Questing",
        sourceType = "Achievement",
        source = "Hemet Nesingwary: The Collected Quests",
        acquisition = "Difficulty: Medium - Finish all three legacy hunting chains and their prerequisite quests.\n\n1. Enable trivial-quest tracking and check the three component achievements: The Green Hills of Stranglethorn, Hills Like White Elekk and The Snows of Northrend. Complete any branch still missing; visiting Hemet without doing the hunts is insufficient.\n\n2. At Nesingwary's Expedition in NORTHERN Stranglethorn, take Barnil Stonepot's Welcome to the Jungle. Finish the tiger, panther and raptor hunting chains, then Hemet Nesingwary Jr.'s Big Game Hunter: kill King Bangalash, loot the quest item and turn it in. The obsolete multi-page book collection is not this current hunting requirement.\n\n3. At Nesingwary Safari in OUTLAND Nagrand, take Clefthoof, Talbuk and Windroc Mastery together. Finish each chain and its named hunt (Banthar, Bach'lor and Gutripper), then complete The Ultimate Bloodsport by killing Tusker, looting the heart and returning to Hemet.\n\n4. In Sholazar Basin, start at Nesingwary Base Camp: Weslex's engine/parts quests and Debaar's Venture Co. Misadventure -> Wipe That Grin Off His Face. Follow Rhino, Dreadsaber and Crocolisk Mastery. Include Oracle Soo-rahm's offering and Bones of Nozronn when the rhino chain sends you there.\n\n5. Once those three Sholazar hunts are complete, take In Search of Bigger Game to Dorian Drakestalker. Finish Securing the Bait, Sharpening Your Talons and the follow-ups at his camp, including My Pet Roc, A Mammoth Undertaking and Reagent Agent. Complete Post-partum Aggression and its turn-in, then check all three meta criteria.",
        stepCount = 5,
        waypoints = {
            { mapID = 50, x = 0.442, y = 0.222, step = 2, label = "Barnil Stonepot - Stranglethorn introductions" },
            { mapID = 50, x = 0.44, y = 0.23399999999999999, step = 2, label = "Hemet Jr. - Big Game Hunter turn-in" },
            { mapID = 50, x = 0.475, y = 0.585, step = 2, label = "King Bangalash - final Stranglethorn hunt" },
            { mapID = 107, x = 0.715, y = 0.40700000000000003, step = 3, label = "Nesingwary Safari - three hunting chains" },
            { mapID = 107, x = 0.444, y = 0.659, step = 3, label = "Tusker - The Ultimate Bloodsport" },
            { mapID = 119, x = 0.25, y = 0.58, step = 4, label = "Weslex Quickwrench - engine and parts introduction" },
            { mapID = 119, x = 0.27, y = 0.59, step = 4, label = "Debaar and Nesingwary Base Camp hunts" },
            { mapID = 119, x = 0.25, y = 0.66, step = 4, label = "Oracle Soo-rahm - rhino-chain follow-ups" },
            { mapID = 119, x = 0.42, y = 0.28, step = 5, label = "Dorian Drakestalker - Bigger Game and final hunts" },
        },
        tips = "Old comments' kill counts and level-64/75 requirements predate later quest and level changes; use each current quest objective. Turn in the final quests, rather than stopping after a named kill.",
        sources = {
            "https://www.wowhead.com/achievement=941#comments:id=1424501",
            "https://www.wowhead.com/achievement=938#comments:id=548389",
            "https://www.wowhead.com/achievement=938#comments:id=1044964",
            "https://www.wowhead.com/achievement=940#comments:id=1642180",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=941",
        sourceURL = "https://www.wowhead.com/achievement=941#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Finish all three legacy hunting chains and their prerequisite quests.",
        difficulty = "medium",
    },
    [942] = {
        achievementId = 942,
        name = "The Diplomat",
        category = "Reputation",
        sourceType = "Achievement",
        source = "The Diplomat",
        acquisition = "Difficulty: Medium - Complete several dungeon-tabard or repeatable reputation routes.\n\n1. Track Timbermaw Hold, Sporeggar and Kurenai. Check your current bars first; these are three separate reputations, and buying a faction's mount is not an additional requirement.\n\n2. Start Timbermaw at Nafien beside the northern Felwood tunnel (64.0, 10.4). Enable trivial-quest tracking and complete his Deadwood of the North and Disarming Bears introductions. Kill the hostile Deadwood around Felpaw Village and loot their Deadwood Headdress Feathers. Do not attack the friendly Timbermaw inside the tunnel.\n\n3. Continue the Felpaw Village circuit and hand FIVE feathers at a time to Nafien through Feathers for Nafien. Each hand-in gives 2,000 reputation before temporary bonuses. Later Retail replies confirm that kill reputation can continue at Revered, so keep killing/looting while finishing the bar. Old instructions to save hundreds of feathers or stop all kills at Revered use older values.\n\n4. For Sporeggar, set NORMAL difficulty, swim through Coilfang Reservoir's central pipe in Zangarmarsh and enter Underbog. Accept Bring Me A Shrubbery! from T'shu just inside. This current dungeon version needs no prior Friendly reputation with Sporeggar. Collect Sanguine Hibiscus from glowing red ground plants and creature loot; Herbalism is unnecessary.\n\n5. For short flower runs, clear the first ground-floor area, Hungarfen's surroundings and the path up to the first nagas, picking up every Hibiscus. Return to T'shu with at least FIVE actual flowers; a premature completed marker is not enough. Finish the first quest, then use Bring Me Another Shrubbery! repeatedly. Leave, reset Normal and repeat when flowers run out. Alternatively buy the unbound flowers from the Auction House: 280 cover Neutral to Exalted at the reported 750 reputation per five, before bonuses or kill gains. Buy less when already partway through the bar.\n\n6. For Kurenai, begin with Ikuti at Orebor Harborage, Zangarmarsh (41.8, 27.2), and finish the available Kurenai introductions. Continue at Telaar in Nagrand, OUTLAND, to unlock its quests and the warbead turn-in at Friendly. Do not travel to Draenor's Nagrand for this faction.\n\n7. Finish the available Telaar quests to reduce the remaining grind, then kill Nagrand ogres around Laughing Skull Ruins/Ring of Blood or Warmaul Hill. Loot every corpse for Obsidian Warbeads. Other hostile Nagrand groups can give kill reputation, but the ogres also supply the repeatable turn-in item.\n\n8. Return to Warden Moi'bff Jill at Telaar and turn in sets of TEN Obsidian Warbeads for 500 reputation before bonuses. Keep alternating kills and hand-ins until Kurenai reaches Exalted. The eight ordinary reputation talbuks are optional purchases afterwards; Halaa battle tokens are unrelated to completing this reputation.\n\n9. Check all three Exalted criteria and select the Diplomat title when complete. Use the actual standing for how many turn-ins remain; old guides' totals include superseded reputation values and removed guild bonuses.",
        stepCount = 9,
        waypoints = {
            {
                mapID = 77,
                x = 0.64,
                y = 0.10400000000000001,
                step = 2,
                label = "Nafien - Deadwood of the North and Disarming Bears",
            },
            { mapID = 77, x = 0.625, y = 0.12, step = 2, label = "Felpaw Village - hostile Deadwood" },
            { mapID = 77, x = 0.625, y = 0.12, step = 3, label = "Felpaw Village - feather circuit" },
            { mapID = 77, x = 0.64, y = 0.10400000000000001, step = 3, label = "Nafien - five-feather hand-ins" },
            { mapID = 102, x = 0.504, y = 0.409, step = 4, label = "Coilfang Reservoir - underwater pipe" },
            { mapID = 102, x = 0.542, y = 0.345, step = 4, label = "Underbog - T'shu is just inside" },
            { mapID = 102, x = 0.542, y = 0.345, step = 5, label = "Normal Underbog - flower runs and five-flower hand-ins" },
            { mapID = 102, x = 0.418, y = 0.272, step = 6, label = "Ikuti - Orebor Harborage Kurenai introduction" },
            { mapID = 107, x = 0.5479999999999999, y = 0.708, step = 6, label = "Telaar - continue faction quests" },
            { mapID = 107, x = 0.42, y = 0.23, step = 7, label = "Laughing Skull Ruins - ogre and warbead search area" },
            { mapID = 107, x = 0.28, y = 0.23, step = 7, label = "Warmaul Hill - alternative ogre search area" },
            { mapID = 107, x = 0.5479999999999999, y = 0.708, step = 8, label = "Warden Moi'bff Jill - ten-warbead hand-ins" },
        },
        tips = "Recent comments report Warband-wide achievement handling; inspect the meta before repeating a reputation already Exalted elsewhere. Sporeggar's current quest data displays 250, but later Retail comments consistently report 750 earned per five flowers; use the actual reputation message to calculate remaining hand-ins. Fixed farming times and old guild reputation perks are excluded.",
        sources = {
            "https://www.wowhead.com/achievement=942#comments:id=1373822",
            "https://www.wowhead.com/comment/show-replies?id=1373822",
            "https://www.wowhead.com/achievement=942#comments:id=6063095",
            "https://www.wowhead.com/achievement=943#comments:id=619827",
            "https://www.wowhead.com/comment/show-replies?id=619827",
            "https://www.wowhead.com/achievement=943#comments:id=899749",
            "https://www.wowhead.com/comment/show-replies?id=1324862",
            "https://www.wowhead.com/quest=29691#comments:id=5671134",
            "https://www.wowhead.com/quest=29692#comments:id=2317891",
            "https://www.wowhead.com/quest=29692#comments:id=6038363",
            "https://www.wowhead.com/npc=18008/ikuti",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=942",
        sourceURL = "https://www.wowhead.com/achievement=942#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Complete several dungeon-tabard or repeatable reputation routes.",
        difficulty = "medium",
    },
