    [953] = {
        achievementId = 953,
        name = "Guardian of Cenarius",
        category = "Reputation",
        sourceType = "Achievement",
        source = "Guardian of Cenarius",
        acquisition = "Difficulty: Medium - Complete several dungeon-tabard or repeatable reputation routes.\n\n1. Track BOTH Cenarion Expedition and Cenarion Circle. They are different factions on different continents; Exalted with only one is insufficient. Check which bar still needs reputation.\n\n2. For Cenarion Expedition, fly to Coilfang Reservoir in Zangarmarsh (50.3, 40.8). Swim through the central pipe and enter the Steamvault portal in the cavern. Clear trash and bosses; activate the panels after Thespia and Steamrigger to open Kalithresh's room.\n\n3. Repeat Normal Steamvault while kills award reputation. If Normal kills stop just below Exalted, finish with Heroic Steamvault, Slave Pens or Underbog, or remaining Expedition quests. The old Coilfang Armament turn-in is unavailable.\n\n4. For Cenarion Circle without waiting for raid resets, buy Encrypted Twilight Texts (item 20404) from the Auction House. You need ten per hand-in. From exactly 0/3,000 Neutral, 840 texts cover the full 42,000 reputation at 500 per ten; buy fewer if already partway through the bar or using a temporary reputation bonus. Compare the total cost before buying.\n\n5. Travel to Silithus. If Cenarion Hold is missing because the zone shows Sargeras' wound, speak to Zidormi near Valor's Rest in the northeastern corner (78.8, 22.0), on top of the cliff, and select Silithus BEFORE the wound. This old phase remains accessible in Retail.\n\n6. Find Bor Wildmane beside the moonwell in Cenarion Hold (53.2, 35.0). Complete Secret Communication with your first TEN texts to unlock Encrypted Twilight Texts. Accept, turn in and reaccept that repeatable quest with each next set of ten until Exalted. Bring the actual texts in your bags; you do not need windstone summons or cultist clothing.\n\n7. For a route without buying texts, enter the RUINS of Ahn'Qiraj, the smaller raid beyond southern Silithus's Scarab Wall. Clear elite trash and bosses, including Rajaxx's waves, instead of rushing only to Ossirian. These kills provide Cenarion Circle reputation through Exalted. Repeat after its raid lockout resets; do not use the Temple of Ahn'Qiraj as the same clear.\n\n8. Finish whichever bar remains: repeat the Circle text hand-ins or return for another Ruins lockout, and complete remaining Expedition Heroics after their resets. Verify BOTH factions are Exalted. The Cenarion War Hippogryph is an optional purchase afterward, not a title requirement.",
        stepCount = 8,
        waypoints = {
            { mapID = 102, x = 0.503, y = 0.408, step = 2, label = "Coilfang Reservoir - underwater pipe" },
            { mapID = 102, x = 0.504, y = 0.33299999999999996, step = 2, label = "Steamvault portal inside reservoir" },
            { mapID = 102, x = 0.489, y = 0.35600000000000004, step = 3, label = "Slave Pens - additional Heroic reputation" },
            { mapID = 102, x = 0.542, y = 0.34600000000000003, step = 3, label = "Underbog - additional Heroic reputation" },
            { mapID = 81, x = 0.7879999999999999, y = 0.22, step = 5, label = "Zidormi - return Silithus to before the wound" },
            { mapID = 81, x = 0.532, y = 0.35, step = 6, label = "Bor Wildmane - first and repeat ten-text hand-ins" },
            { mapID = 81, x = 0.36, y = 0.847, step = 7, label = "Scarab Wall - approach the RUINS portal" },
        },
        tips = "Twilight Text hand-ins can finish Cenarion Circle without waiting for another Ruins lockout. Reputation bonuses reduce the number needed, so check the bar before buying another stack. Use Steamvault and the additional Heroics for Expedition. Old Windstone summons and Coilfang Armament turn-ins are unavailable.",
        sources = {
            "https://www.wowhead.com/achievement=953#comments:id=965814",
            "https://www.wowhead.com/achievement=953#comments:id=2460500",
            "https://www.wowhead.com/achievement=953#comments:id=3244934",
            "https://www.wowhead.com/comment/show-replies?id=3244934",
            "https://www.wowhead.com/zone=3429/ruins-of-ahnqiraj",
            "https://www.wowhead.com/quest=8319#comments:id=5542755",
            "https://www.wowhead.com/comment/show-replies?id=5542755",
            "https://www.wowhead.com/quest=8319#comments:id=5191775",
            "https://www.wowhead.com/comment/show-replies?id=5191775",
            "https://www.wowhead.com/npc=15306/bor-wildmane",
            "https://www.wowhead.com/npc=128607/zidormi",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=953",
        sourceURL = "https://www.wowhead.com/achievement=953#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Complete several dungeon-tabard or repeatable reputation routes.",
        difficulty = "medium",
    },
    [964] = {
        achievementId = 964,
        name = "Going Down?",
        category = "Exploration",
        sourceType = "Achievement",
        source = "Going Down?",
        acquisition = "Difficulty: Easy - Use the mapped platform for one surviving fall.\n\n1. Reach Valdrakken and heal to full. Go to the raised platform in the Sapphire Enclave near the Relaxing Dragon at 38.0, 28.0. Check the lower landing area before stepping off.\n\n2. Walk straight off the platform in the direction the dragon faces and fall to the lower city without dying. The required drop is 65 yards; a small jump from a low wall is not enough.\n\n3. Check the achievement after landing. You only need one surviving fall. If using another location, choose a known survivable drop or a fall-protection ability; do not assume any flight high above the city will be survivable.",
        stepCount = 3,
        waypoints = { { mapID = 2112, x = 0.38, y = 0.28, step = 1, label = "Sapphire Enclave platform - Relaxing Dragon" } },
        tips = "Begin at full health and use the specified platform and direction. A fall well beyond the required 65 yards can still be fatal. This route needs neither alcohol nor Brewfest.",
        sources = {
            "https://www.wowhead.com/achievement=964#comments:id=5692093",
            "https://www.wowhead.com/npc=187640/relaxing-dragon",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=964",
        sourceURL = "https://www.wowhead.com/achievement=964#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Use the mapped platform for one surviving fall.",
        difficulty = "easy",
    },
    [973] = {
