    [978] = {
        achievementId = 978,
        name = "3000 Quests Completed",
        category = "Questing",
        sourceType = "Achievement",
        source = "3000 Quests Completed",
        acquisition = "Difficulty: Hard - This large cumulative quest total requires substantial questing across zones.\n\n1. Track this achievement to see how many quest completions it currently recognises. Choose an unfinished zone story instead of repeatedly accepting and abandoning the same quest.\n\n2. Enable low-level quest tracking on the minimap if you outlevel the area. Complete the ordinary quests at one hub, turn them in and follow their follow-ups to the next hub; introductory and short delivery quests also provide completions.\n\n3. For an accessible old-world start, Alliance can take Marshal Dughan's quests in Goldshire, Elwynn Forest (42.2, 65.8); Horde can take Gar'Thok's quests in Razor Hill, Durotar (51.8, 43.4). Use a hub your character has not already completed, pick up its nearby side quests and finish the follow-ups before travelling elsewhere.\n\n4. Continue through unfinished zone stories until the counter reaches 3000. The quest-map chapters for Loremaster help identify unfinished stories, but this count milestone does not itself award Loremaster. Dungeon quests and class/profession introductions can fill gaps; old cloth donations and removed attunements are unnecessary.\n\n5. Check progress after several hand-ins when trying a repeatable activity. Many repeatables and modern world activities do not behave like unique story quests, so switch to an unfinished quest line if that activity does not move the counter.",
        stepCount = 5,
        waypoints = {
            {
                mapID = 37,
                x = 0.42200000000000004,
                y = 0.6579999999999999,
                step = 3,
                label = "Marshal Dughan - optional Alliance quest hub",
            },
            { mapID = 1, x = 0.518, y = 0.434, step = 3, label = "Gar'Thok - optional Horde quest hub" },
        },
        tips = "Use the achievement counter rather than the Statistics page's total, which can include dailies counted separately. If an old character's counter looks stale after a loading screen, complete a new quest and check again. Old fixed quest totals per continent and before-Cataclysm completion deadlines are obsolete.",
        sources = {
            "https://www.wowhead.com/achievement=32#comments:id=475198",
            "https://www.wowhead.com/achievement=978#comments:id=417643",
            "https://www.wowhead.com/achievement=978#comments:id=634460",
