    [1157] = {
        achievementId = 1157,
        name = "Duel-icious",
        category = "PvP",
        sourceType = "Achievement",
        source = "Duel-icious",
        acquisition = "Difficulty: Easy - One player kill, one ordinary duel or one correctly timed corpse emote is enough.\n\n1. Meet a willing player outside a city or another area where ordinary duels are permitted. Select them and type /duel; wait for them to accept and for the countdown.\n\n2. Win the duel by reducing their health to the duel's defeat threshold. Alternatively, the other player can type /forfeit after the duel begins; comments confirm that a conceded duel awards the win.\n\n3. Check the achievement. You do not need an arena queue, a killing blow that actually kills the player, or an opponent of your own level. You can switch roles if the other player also needs a duel win.",
        stepCount = 3,
        waypoints = {},
        tips = "Use an ordinary consenting duel, rather than a hostile PvP attack. Mounted Argent Tournament duels also have reported credit, but are unnecessary for this simple route.",
        sources = {
            "https://www.wowhead.com/achievement=1157#comments:id=756572",
            "https://www.wowhead.com/achievement=1157#comments:id=853773",
            "https://www.wowhead.com/achievement=1157#comments:id=1165427",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1157",
        sourceURL = "https://www.wowhead.com/achievement=1157#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "One player kill, one ordinary duel or one correctly timed corpse emote is enough.",
        difficulty = "easy",
    },
    [1159] = {
        achievementId = 1159,
        name = "Just the Two of Us: 2200",
        category = "PvP",
        sourceType = "Achievement",
        source = "Just the Two of Us: 2200",
        acquisition = "Difficulty: Hard - High personal rating needs sustained competitive performance and suitable teammates.\n\n1. Form a group of 2 players and enter the RATED 2v2 arena queue from the Rated PvP panel. A Solo Shuffle rating, rated battleground rating or unrated skirmish win is not this bracket's personal rating.\n\n2. Play completed matches and raise YOUR personal rating in that bracket to at least 2200. Inspect your character's rating after the result screen; a teammate already being above the threshold does not grant you their rating.\n\n3. Keep playing through wins and losses until your own rating reaches the target, then check the achievement. No exact equality is required: crossing above 2200 is enough. Old arena-team purchase and team-rating instructions are obsolete.",
        stepCount = 3,
        waypoints = {},
        tips = "This is a rating milestone, not a promise that a fixed number of wins will achieve it. Matchmaking rating and personal rating are different values; read the rated panel's personal bracket rating.",
        sources = {
            "https://www.wowhead.com/achievement=402#comments:id=1395845",
            "https://www.wowhead.com/achievement=1159#comments:id=1395874",
        },
