            { mapID = 37, x = 0.34, y = 0.54, step = 3, label = "Rabbit search area" },
            { mapID = 37, x = 0.425, y = 0.662, step = 4, label = "Goldshire inn - Chicken" },
            { mapID = 37, x = 0.418, y = 0.6940000000000001, step = 4, label = "South of Goldshire - Cow" },
            { mapID = 37, x = 0.42, y = 0.7, step = 4, label = "South of Goldshire - Sheep" },
            { mapID = 37, x = 0.452, y = 0.6679999999999999, step = 4, label = "Crystal Lake western bank - Small Frog" },
            { mapID = 47, x = 0.21, y = 0.46, step = 5, label = "Raven Hill graveyard - Skunk" },
            { mapID = 48, x = 0.21, y = 0.7240000000000001, step = 5, label = "Loch Modan western approach - Ram" },
            { mapID = 1, x = 0.4363, y = 0.3034, step = 6, label = "Tor'kren Farm - Swine" },
            { mapID = 1, x = 0.348, y = 0.434, step = 6, label = "Watershed - Toad" },
            { mapID = 1, x = 0.408, y = 0.17600000000000002, step = 6, label = "Northern Durotar - Hare" },
            { mapID = 10, x = 0.36, y = 0.436, step = 7, label = "Forgotten Pools region - Gazelle and Prairie Dog search" },
            { mapID = 78, x = 0.26, y = 0.45, step = 8, label = "Un'Goro - Parrot search area" },
            { mapID = 111, x = 0.59, y = 0.22, step = 9, label = "Lower City northern bridge - Ewe" },
            { mapID = 114, x = 0.6920000000000001, y = 0.29, step = 10, label = "Geyser Fields - Borean Frog" },
            { mapID = 114, x = 0.774, y = 0.318, step = 10, label = "North of Taunka'le - Steam Frog" },
            { mapID = 114, x = 0.37799999999999995, y = 0.23, step = 10, label = "Coldarra coast cave - Shore Crab" },
        },
        tips = "Moving critters are search-area pins, not guaranteed stationary spawns. Old lists call Small Frog 'Frog' and Shore Crab 'Crab'. Only twelve of these species have the matching captured-pet shortcut; Borean Frog, Steam Frog, Cow, Deer, Ewe, Gazelle, Ram, Sheep and Swine still need their world targets.",
