                step = 3,
                label = "Xan'tish - walking snake vendor; search nearby",
            },
            { mapID = 88, x = 0.628, y = 0.584, step = 3, label = "Halpa - Prairie Dog" },
            {
                mapID = 94,
                x = 0.44799999999999995,
                y = 0.716,
                step = 3,
                label = "Jilanne - three dragonhawks",
                mapName = "Eversong Woods (Burning Crusade)",
            },
            {
                mapID = 109,
                x = 0.435,
                y = 0.35200000000000004,
                step = 4,
                label = "Dealer Rashaad - upper Stormspire, beside inn",
            },
            { mapID = 210, x = 0.426, y = 0.6920000000000001, step = 5, label = "Narkk - Cockatiel" },
            { mapID = 64, x = 0.8540000000000001, y = 0.914, step = 5, label = "Plucky Johnson - Ancona Chicken" },
            { mapID = 84, x = 0.6920000000000001, y = 0.25, step = 7, label = "Audrey Burnhep - Battle Pet Training" },
            { mapID = 85, x = 0.526, y = 0.588, step = 7, label = "Varzok - Battle Pet Training" },
            {
                mapID = 37,
                x = 0.42200000000000004,
                y = 0.6579999999999999,
                step = 7,
                label = "Goldshire - nearby low-level wild-pet search",
            },
            { mapID = 1, x = 0.518, y = 0.434, step = 7, label = "Razor Hill - nearby low-level wild-pet search" },
            {
                mapID = 23,
                x = 0.5379999999999999,
                y = 0.086,
                step = 3,
                label = "Zidormi - enter Burning Crusade Quel'Thalas for Jilanne",
            },
        },
        tips = "Use the achievement's distinct-species counter rather than a Journal total inflated by duplicates. Basic vendor pets can be learned without a pet-battle team. Stinker/Little Fawn may appear directly in the Journal; relog once if the achievement is complete but its reward is missing. Retired promotional pets and real-money purchases are unnecessary.",
        sources = {
            "https://www.wowhead.com/achievement=15#comments:id=424584",
            "https://www.wowhead.com/comment/show-replies?id=424584",
            "https://www.wowhead.com/achievement=1248#comments:id=424586",
