                step = 5,
                label = "Washed-Up Mage - learn Kungaloosh",
                mapName = "Dalaran Underbelly (Northrend)",
            },
            { mapID = 108, x = 0.387, y = 0.128, step = 6, label = "Old Man Barlo - fishing bag chance for Lager recipe" },
