    [1576] = {
        achievementId = 1576,
        name = "Of Blood and Anguish",
        category = "Questing",
        sourceType = "Achievement",
        source = "Of Blood and Anguish",
        acquisition = "Difficulty: Easy - Complete two straightforward legacy arena quest chains at current max level.\n\n1. On the character you will use for both chains, travel to the Ring of Blood in OUTLAND Nagrand. Speak to Gurgthock (42.7, 20.7), not an unrelated arena NPC in Draenor's Nagrand.\n\n2. Complete the six Ring of Blood quests in sequence, returning for each turn-in and accepting the next fight. Finish through The Final Challenge and claim the reward. Stay in the arena so each spawned opponent is part of your active quest.\n\n3. Travel to the Amphitheater of Anguish in Zul'Drak (48.4, 56.4). Speak to Gurgthock and complete every arena quest offered in the chain, including its elemental encounter and final champion.\n\n4. Turn in The Champion of Anguish after the final mounted opponent. His mount becomes usable during the fight and can help a character levelling through the area; a high-level character can generally overpower these old encounters. Check both completed quest-chain criteria.",
        stepCount = 4,
        waypoints = {
            { mapID = 107, x = 0.42700000000000005, y = 0.207, step = 1, label = "Gurgthock - Ring of Blood" },
            { mapID = 121, x = 0.484, y = 0.564, step = 3, label = "Gurgthock - Amphitheater of Anguish" },
        },
        tips = "The order of the two chains does not matter. A 2023 comment reports they must be completed on the same character, so this route does not depend on combining partial alt progress. The old mandatory five-player group and gold-return estimates are not Retail requirements.",
        sources = {
            "https://www.wowhead.com/achievement=1576#comments:id=453458",
            "https://www.wowhead.com/achievement=1576#comments:id=1509298",
            "https://www.wowhead.com/achievement=1576#comments:id=5708049",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1576",
        sourceURL = "https://www.wowhead.com/achievement=1576#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Complete two straightforward legacy arena quest chains at current max level.",
        difficulty = "easy",
    },
    [1795] = {
        achievementId = 1795,
        name = "Lunch Lady",
        category = "Professions",
        sourceType = "Achievement",
        source = "Lunch Lady",
        acquisition = "Difficulty: Easy - Learn a small batch of readily available trainer and vendor recipes.\n\n1. Use one cook and track the recipe counter. Learn missing recipes from Cooking trainers; train the relevant expansion's Cooking tier when required. Recipes learned on a different character are not recipes learned by this cook.\n\n2. A large inexpensive trainer batch is Sungshin Ironpaw at Halfhill Market, Valley of the Four Winds (53.5, 51.2). Learn Pandaria Cooking and her missing everyday recipes, including Sliced Peaches, Fish Cake and Yak Cheese Curds. Raise that tier to 5 and return for Rice Pudding. Her current trainer list offers twenty dishes; the Cooking skill itself is not a twenty-first dish. Many use supplies sold at the market rather than rare ingredients.\n\n3. For recipe scrolls, Alliance can visit Kendor Kabonka upstairs in the Pig and Whistle, Old Town, Stormwind: he sells thirteen low-level recipes, including Westfall Stew, Crocolisk Steak and Gooey Spider Cake. Both factions can use Kelsey Yance in Booty Bay, who sells nine recipes including Giant Clam Scorcho, Cooked Glossy Mightfish, Filet of Redgill and Hot Smoked Bass. Buy only unlearned scrolls your cook can use, then right-click to LEARN each one; purchasing a finished food is different.\n\n4. In Shattrath's World's End Tavern, train Outland Cooking from Kylene and return as its skill increases. Her three dishes are Stewed Trout, Fisherman's Feast and Hot Buttered Trout; the latter two require Outland Cooking 75. Other Outland food/fishing vendors supply more scrolls. This preserves the useful older-vendor route without depending on removed original-world quests.\n\n5. In NORTHREND Dalaran, learn unlearned trainer recipes and buy missing recipes from Derek Odds beside Katherine Lee for Alliance, or Misensi beside Awilo Lon'gomba for Horde. These suppliers use Epicurean's Awards. Do their cooking dailies and the capital-city daily to earn awards; see Cooking Award for the repeatable Waterlogged Recipe alternative. Open the recipe's Unlearned entry to see its tier, required skill and source.\n\n6. If only a few recipes remain, search the Auction House's Cooking recipes for inexpensive unlearned scrolls before waiting through many daily resets. Compare the scroll's name and required Cooking tier with this character's known recipes. Optional holiday recipes also count when their events are active; waiting for a holiday is unnecessary when a permanent unlearned recipe is available.\n\n7. Continue learning distinct recipes on this character until the counter reaches 25. Cooking the same dish repeatedly raises skill when eligible, but does not add another learned recipe. You do not need a removed recipe, every recipe in the game, or every faction-exclusive recipe to reach this target.",
        stepCount = 7,
        waypoints = {
            { mapID = 376, x = 0.535, y = 0.512, step = 2, label = "Sungshin Ironpaw - twenty Pandaria everyday recipes" },
            {
                mapID = 84,
                x = 0.7659999999999999,
                y = 0.53,
                step = 3,
                label = "Kendor Kabonka - thirteen scrolls; upstairs Pig and Whistle",
            },
            { mapID = 210, x = 0.428, y = 0.69, step = 3, label = "Kelsey Yance - nine neutral recipe scrolls" },
            { mapID = 111, x = 0.75, y = 0.326, step = 4, label = "Kylene - three Outland recipes, World's End Tavern" },
            {
                mapID = 125,
                x = 0.40399999999999997,
                y = 0.6579999999999999,
                step = 5,
                label = "Derek Odds and Katherine Lee - Alliance Northrend recipes",
            },
            { mapID = 125, x = 0.7, y = 0.386, step = 5, label = "Misensi and Awilo Lon'gomba - Horde Northrend recipes" },
        },
        tips = "Stop as soon as your target credits. Older comments claiming you need Thistle Tea, Dirge's Kickin' Chimaerok Chops or every seasonal recipe predate the larger recipe pool. If newly learned recipes appear absent from the counter, relog once and learn another genuinely missing recipe rather than buying duplicates.",
        sources = {
            "https://www.wowhead.com/achievement=1798#comments:id=428820",
            "https://www.wowhead.com/comment/show-replies?id=428820",
            "https://www.wowhead.com/achievement=1799#comments:id=952463",
            "https://www.wowhead.com/achievement=1799#comments:id=1884755",
            "https://www.wowhead.com/comment/show-replies?id=1884755",
            "https://www.wowhead.com/npc=64231/sungshin-ironpaw",
            "https://www.wowhead.com/npc=2664/kelsey-yance",
            "https://www.wowhead.com/npc=19186/kylene",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=1795",
        sourceURL = "https://www.wowhead.com/achievement=1795#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Learn a small batch of readily available trainer and vendor recipes.",
        difficulty = "easy",
    },
