            { mapID = 23, x = 0.046, y = 0.35600000000000004, step = 4, label = "Western Eastern Plaguelands - Scorpid" },
            { mapID = 23, x = 0.044000000000000004, y = 0.358, step = 4, label = "Western Eastern Plaguelands - Spider" },
            {
                mapID = 23,
                x = 0.5379999999999999,
                y = 0.086,
                step = 4,
                label = "Zidormi and old Ghostlands portal - reach the Larva map",
            },
            {
                mapID = 95,
                x = 0.20600000000000002,
                y = 0.526,
                step = 4,
                label = "Burning Crusade Ghostlands - Larva",
                mapName = "Ghostlands (Burning Crusade)",
            },
            { mapID = 15, x = 0.418, y = 0.106, step = 5, label = "Northern Badlands - Gold Beetle" },
            { mapID = 36, x = 0.168, y = 0.218, step = 5, label = "Northwestern Burning Steppes - Fire Beetle" },
            { mapID = 84, x = 0.442, y = 0.7979999999999999, step = 6, label = "Stormwind grass - Squirrel" },
            { mapID = 84, x = 0.604, y = 0.688, step = 6, label = "Stormwind canal - Rat" },
            { mapID = 52, x = 0.292, y = 0.45, step = 6, label = "Westfall - Mouse search if still missing" },
            { mapID = 52, x = 0.322, y = 0.48200000000000004, step = 6, label = "Westfall - Snake search" },
        },
        tips = "Use /targetexact followed by the missing critter's name if it is hard to click, then mark it with a raid target icon to locate it. The old Moccasin is now Water Snake and Scorpion is displayed as Scorpid. Maggot does not substitute for Devouring Maggot. Roaming critter markers identify search areas; the Grizzly Hills pack moves past its pin.",
        sources = {
            "https://www.wowhead.com/achievement=2556#comments:id=572897",
