    [4476] = {
        achievementId = 4476,
        name = "Looking For More",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Looking For More",
        acquisition = "Difficulty: Easy - Finish a few Random Heroics with randomly matched teammates.\n\n1. Open Group Finder > Dungeon Finder and choose an available RANDOM HEROIC queue. Selecting a specific Heroic dungeon or walking through a dungeon portal does not satisfy this queue requirement.\n\n2. Queue alone for the most random teammates per completion, or bring a friend if that makes queuing easier. You and players already in your party when you queue do not count as random teammates. Queue afresh after a completed run; continuing with the same assembled party can stop it adding new random teammates.\n\n3. Finish the dungeon, including its final boss. Repeat random Heroics until the achievement counter reaches 10 random players. A full run with four qualifying teammates can add four, so this counts PLAYERS rather than requiring 10 separate dungeons.\n\n4. If Random Heroic is absent, inspect a Heroic in the Specific Dungeons list to see its current level and equipment requirements, meet those requirements, then return to the RANDOM queue. Changing your portrait's dungeon difficulty does not turn a Random Normal queue into Random Heroic.\n\n5. At 10 random players, check Looking For More. Continue toward Looking For Many at 50 and Looking For Multitudes at 100.",
        stepCount = 5,
        waypoints = {},
        tips = "Use the counter on the achievement itself to confirm progress. Do not assume that Random Normal, Follower or Timewalking runs qualify; later comments report inconsistent Timewalking credit. This achievement has no fixed map location.",
        sources = {
            "https://www.wowhead.com/achievement=4476#comments:id=910570",
            "https://www.wowhead.com/achievement=4477#comments:id=1112369",
            "https://www.wowhead.com/achievement=4478#comments:id=5451389",
            "https://www.wowhead.com/achievement=4478#comments:id=6462728",
            "https://www.wowhead.com/comment/show-replies?id=5451389",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=4476",
        sourceURL = "https://www.wowhead.com/achievement=4476#comments",
        reviewedAt = "2026-11-04",
        difficultyReason = "Finish a few Random Heroics with randomly matched teammates.",
        difficulty = "easy",
    },
    [4477] = {
        achievementId = 4477,
        name = "Looking For Many",
        category = "Dungeons",
        sourceType = "Achievement",
        source = "Looking For Many",
        acquisition = "Difficulty: Medium - Finish repeated Random Heroics with qualifying random teammates.\n\n1. Open Group Finder > Dungeon Finder and choose an available RANDOM HEROIC queue. Selecting a specific Heroic dungeon or walking through a dungeon portal does not satisfy this queue requirement.\n\n2. Queue alone for the most random teammates per completion, or bring a friend if that makes queuing easier. You and players already in your party when you queue do not count as random teammates. Queue afresh after a completed run; continuing with the same assembled party can stop it adding new random teammates.\n\n3. Finish the dungeon, including its final boss. Repeat random Heroics until the achievement counter reaches 50 random players. A full run with four qualifying teammates can add four, so this counts PLAYERS rather than requiring 50 separate dungeons.\n\n4. If Random Heroic is absent, inspect a Heroic in the Specific Dungeons list to see its current level and equipment requirements, meet those requirements, then return to the RANDOM queue. Changing your portrait's dungeon difficulty does not turn a Random Normal queue into Random Heroic.\n\n5. At 50 random players, check the Patient title in your character's title list. Continue the same activity toward Looking For Multitudes and its Perky Pug reward.",
        stepCount = 5,
