    [6566] = {
        achievementId = 6566,
        name = "Just a Pup",
        source = "Just a Pup",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Raise one pet to level 5.",
        acquisition = "Difficulty: Easy - Raise one pet to level 5.\n\n1. Learn Battle Pet Training from Audrey Burnhep in Stormwind or Varzok in Orgrimmar. Put a healthy battle-capable pet into your Pet Journal's team and enable wild-pet tracking on the minimap.\n\n2. Win wild-pet or unlocked tamer battles with the pet participating and surviving. Start with opponents near its level. As your team improves, let a stronger pet finish after the learner has safely participated; a dead learner receives no experience.\n\n3. Raise the pet through level 5 and check credit. Learning a cage already above the target is not the same as raising it through the level yourself. Pet bandages, Revive Battle Pets and stable masters keep the team healthy between battles.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 84,
                x = 0.6940000000000001,
                y = 0.244,
                step = 1,
                label = "Audrey Burnhep - Alliance Battle Pet Training",
