    [6571] = {
        achievementId = 6571,
        name = "That Was Close!",
        source = "That Was Close!",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Trap a wild pet with less than five percent of its own health remaining.",
        acquisition = "Difficulty: Easy - Trap a wild pet with less than five percent of its own health remaining.\n\n1. Start a wild pet battle with a pet that can lower an enemy's health safely. Terrible Turnip's Weakening Blow cannot reduce the target below one health and is particularly useful here.\n\n2. Reduce the WILD TARGET below five percent of its maximum health. Check its actual health numbers; the normal trap threshold of 35% is not low enough.\n\n3. Trap that target and finish the battle successfully. It is the captured pet's health that matters, rather than your character's or active pet's health. Use healing or swaps to survive failed trap rolls without accidentally finishing the target.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 84,
                x = 0.6940000000000001,
                y = 0.244,
                step = 1,
                label = "Audrey Burnhep - Alliance Battle Pet Training",
