    [6590] = {
        achievementId = 6590,
        name = "World Safari",
        source = "World Safari",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Finish all five original continent species collections.",
        acquisition = "Difficulty: Hard - Finish all five original continent species collections.\n\n1. Complete Kalimdor Safari and Eastern Kingdoms Safari. Plan summer Qiraji Guardling, winter Snowy Owl and rain-dependent Baby Ape early, since those availability windows can outlast the rest of the collection.\n\n2. Complete Outland Safari, Northrend Safari and Pandaria Safari. Use each component's species checklist and map choices. Arctic Fox Kit needs snow in Storm Peaks; inspect primary and backline pets across the Pandaria circuit.\n\n3. Capture every required species, finish each battle and verify the five component achievements. Any quality satisfies the species collection. When all five are complete, World Safari awards the Zookeeper title.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 12, 13, 101, 113, 424 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6590",
