    [6607] = {
        achievementId = 6607,
        name = "Taming Azeroth",
        source = "Taming Azeroth",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Complete the five successive regional tamer achievements.",
        acquisition = "Difficulty: Medium - Complete the five successive regional tamer achievements.\n\n1. Start the pet-training introduction with Audrey or Varzok. Finish Taming Eastern Kingdoms on the Alliance route or Taming Kalimdor on the Horde route; the faction counterpart is not an extra requirement for this meta.\n\n2. At each grand master's victory, accept the capital return and the next assignment. Complete Taming Outland, Taming Northrend and Taming Cataclysm, including Antari, Payne and Obalis rather than only the preliminary trainers.\n\n3. Finish all seven Pandaria trainers, with Grand Master Aki last, then check the five regional criteria. Use their individual guides for numbered destinations and family counters. This awards the Tamer title; it is different from forty distinct trainers for the Safari Hat.",
        stepCount = 3,
        waypoints = {
            { mapID = 84, x = 0.6940000000000001, y = 0.244, step = 1, label = "Alliance introduction" },
            { mapID = 85, x = 0.526, y = 0.593, step = 1, label = "Horde introduction" },
            { mapID = 390, x = 0.312, y = 0.742, step = 3, label = "Final grand master - Aki" },
        },
        sources = { "https://www.wowhead.com/achievement=6607#comments:id=1721657" },
        wowheadUrl = "https://www.wowhead.com/achievement=6607",
        sourceURL = "https://www.wowhead.com/achievement=6607#comments",
        reviewedAt = "2026-11-13",
    },
    [6608] = {
        achievementId = 6608,
        name = "Family Reunion",
        source = "Family Reunion",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Capture one wild representative of each of ten pet families.",
        acquisition = "Difficulty: Medium - Capture one wild representative of each of ten pet families.\n\n1. Track the ten families: Aquatic, Beast, Critter, Dragonkin, Elemental, Flying, Humanoid, Magic, Mechanical and Undead. These must be WILD CAPTURES; vendor companions and learned cages do not satisfy the capture criterion.\n\n2. Starting-zone frogs, beasts, rabbits and moths cover Aquatic, Beast, Critter and Flying. For less common families, search Feralas for Nether Faerie Dragon (Dragonkin) and Stunted Yeti (Humanoid), Hillsbrad for Lofty Libram (Magic), New Tinkertown for Fluxfire Feline (Mechanical), and Silverpine for infected wildlife (Undead).\n\n3. For Elemental, use an accessible elemental wild pet such as a shale hatchling or a Lava Crab in Searing Gorge. Inspect the enemy's actual family icon, lower it below 35%, trap it and win. Check the corresponding family criterion after each capture.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 10, 69, 71, 26, 21, 469, 84, 85 },
        sources = { "https://www.wowhead.com/achievement=6608#comments:id=1697733" },
        wowheadUrl = "https://www.wowhead.com/achievement=6608",
        sourceURL = "https://www.wowhead.com/achievement=6608#comments",
        reviewedAt = "2026-11-13",
    },
    [6609] = {
        achievementId = 6609,
        name = "No Favorites",
        source = "No Favorites",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Raise a representative of every family through level 10.",
        acquisition = "Difficulty: Medium - Raise a representative of every family through level 10.\n\n1. Choose one battle-capable pet from each family: Aquatic, Beast, Critter, Dragonkin, Elemental, Flying, Humanoid, Magic, Mechanical and Undead. Bought or already-owned pets are suitable learners if they are BELOW the target level; this is not restricted to wild captures.\n\n2. Raise each chosen learner through level 10 using safe battle participation and surviving for experience, or suitable leveling stones. Use two strong pets to finish suitable wild or tamer encounters after the learner has participated.\n\n3. Check each family separately. Learning a cage already at or above the level does not create a leveling event. Complete any earlier hidden milestone if the later checklist does not display the progress you expect; use the actual achievement award to confirm completion.",
        stepCount = 3,
        waypoints = {
            { mapID = 84, x = 0.6940000000000001, y = 0.244, step = 1, label = "Audrey Burnhep - Alliance training" },
