    [6611] = {
        achievementId = 6611,
        name = "Continental Tamer",
        source = "Continental Tamer",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Complete the five original continent capture checklists.",
        acquisition = "Difficulty: Hard - Complete the five original continent capture checklists.\n\n1. Complete Kalimdor Tamer and Eastern Kingdoms Tamer by successfully capturing a wild pet in every zone listed by each achievement. Keep the tracker open and combine captures with Safari species.\n\n2. Complete Outland Tamer, Northrend Tamer and Pandaria Tamer in the same way. Use original Outland maps rather than Draenor, and earlier Retail phases when a transformed zone hides its original wild pets.\n\n3. Check all five continent achievements. These capture checklists differ from the Taming achievements awarded for defeating named NPC trainers; completing a trainer campaign alone does not finish Continental Tamer.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 12, 13, 101, 113, 424 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6611",
