    [6620] = {
        achievementId = 6620,
        name = "No Time To Heal",
        source = "No Time To Heal",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Five consecutive queued PvP victories with no pet deaths.",
        acquisition = "Difficulty: Hard - Five consecutive queued PvP victories with no pet deaths.\n\n1. Build a balanced three-pet team with recovery, damage prevention and safe swaps. Use Find Battle in the Pet Journal; a direct duel against a friend does not count.\n\n2. Win five consecutive queued PvP battles without allowing any of your pets to die. Switch an endangered pet out before the opponent's finishing attack, taking speed order and damage-over-time effects into account.\n\n3. Heal and adjust the team between matches. Avoid risky PvE pet battles while waiting: comments report that a pet dying in a PvE battle also resets this counter. Do not rely on forfeiting to preserve a streak; the old queue and forfeit tricks have conflicting later corrections.",
        stepCount = 3,
        waypoints = {},
        sources = {
            "https://www.wowhead.com/achievement=6620#comments:id=1854047",
            "https://www.wowhead.com/achievement=6620#comments:id=1799862",
