        reviewedAt = "2026-11-13",
    },
    [6622] = {
        achievementId = 6622,
        name = "Big City Pet Brawler",
        source = "Big City Pet Brawler",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Win wild-pet battles in all eight original faction capitals.",
        acquisition = "Difficulty: Medium - Win wild-pet battles in all eight original faction capitals.\n\n1. Complete Big City Pet Brawlin' - Alliance in Stormwind, Ironforge, Darnassus and the Exodar. An Alliance character makes these visits easier, and their wins are shared for the achievement.\n\n2. Complete Big City Pet Brawlin' - Horde in Orgrimmar, Thunder Bluff, Undercity and the original Silvermoon City. Use an appropriate Horde character and the earlier city phases when necessary.\n\n3. Check both component achievements. You do not have to invade the opposing faction's cities on one character; successful wild-pet battles on separate characters can contribute.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 84, 87, 89, 103, 85, 88, 90, 110 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6622",
