    [7328] = {
        achievementId = 7328,
        name = "Ironpaw Chef",
        source = "Ironpaw Chef",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Learn 240 different cooking recipes on a cook.",
        acquisition = "Difficulty: Medium - Learn 240 different cooking recipes on a cook.\n\n1. Open Cooking and track the 240-recipe counter. Train every inexpensive recipe available for your current skill, including Sungshin's Halfhill starter recipes and the six cooking Ways.\n\n2. Learn missing recipes from cooking vendors and the Auction House. Filter for usable recipes to avoid buying duplicates or recipes this character cannot learn. Alliance cooks can check Kendor Kabonka upstairs in the Pig and Whistle in Stormwind Old Town for inexpensive older recipes.\n\n3. Continue until 240 recipes are learned. Crafting many copies of one food does not increase this counter. This collection spans expansions; older comments report a delayed counter until the earlier 200-recipe milestone, so inspect the actual learned-recipe list if the tracker appears behind.",
        stepCount = 3,
        waypoints = {
            { mapID = 376, x = 0.536, y = 0.512, step = 1, label = "Halfhill - inexpensive cooking training" },
            { mapID = 84, x = 0.762, y = 0.524, step = 2, label = "Pig and Whistle - Alliance recipe vendor Kendor Kabonka" },
        },
