    [7500] = {
        achievementId = 7500,
        name = "Going to Need More Leashes",
        source = "Going to Need More Leashes",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Collect different pet species; duplicate copies do not increase this total.",
        acquisition = "Difficulty: Medium - Collect different pet species; duplicate copies do not increase this total.\n\n1. Open the Pet Journal, filter to Not Collected, and work toward 250 unique species. This counter accepts learned vendor, quest, raid and crafted pets as well as wild captures. The old comment saying every pet must be captured is incorrect.\n\n2. Buy inexpensive missing vendor species, such as Donni Anthania's four Elwynn cats, Dealer Rashaad's Netherstorm companions and Breanni's Dalaran pets. Learn each teaching item or cage; merely carrying it in a bag does not register ownership.\n\n3. Follow the continent Safari guides and capture missing wild species while traveling. Lower a wild pet below 35%, trap it, then win the entire battle. Take an available quality first: rarity is not required for this collection total.\n\n4. Add missing, inexpensive caged species from the Auction House and farm the old raid-pet checklists if desired. Check the species count after learning each; three copies of one species still count as one. There is no need to wait for a retired promotion or buy a store pet to reach this target.",
        stepCount = 4,
        waypoints = {
            { mapID = 37, x = 0.442, y = 0.532, step = 2, label = "Donni Anthania - four cat species" },
            { mapID = 109, x = 0.434, y = 0.35200000000000004, step = 2, label = "Dealer Rashaad - pet vendor" },
            { mapID = 125, x = 0.586, y = 0.396, step = 2, label = "Breanni - Northrend Dalaran" },
        },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=7500",
        sourceURL = "https://www.wowhead.com/achievement=7500#comments",
        reviewedAt = "2026-11-13",
    },
