    [7525] = {
        achievementId = 7525,
        name = "Taming Cataclysm",
        source = "Taming Cataclysm",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "A sequential account unlock and a team of trained battle pets are required.",
        acquisition = "Difficulty: Medium - A sequential account unlock and a team of trained battle pets are required.\n\n1. Start with Audrey Burnhep in Stormwind (Alliance) or Varzok in Orgrimmar (Horde). Complete the introductory healing, leveling and capture lessons, then accept each next tamer quest after winning. The unlock order is your home continent, Outland, Northrend, Cataclysm, then Pandaria. A trainer with no battle dialogue usually means an earlier quest or capital return is unfinished.\n\n2. Defeat Brok at 61.4,32.8. Bring Dragonkin, Mechanical and Beast attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n3. Defeat Bordin Steadyfist at 49.8,57. Bring Aquatic and Beast attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n4. Defeat Goz Banefury at 56.6,56.8. Bring Aquatic, Dragonkin and Mechanical attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n5. Defeat Obalis at 56.6,41.8. Bring Mechanical, Magic and Beast attacks to counter this team. Heal between battles and use rare-quality, appropriately leveled pets; your character's combat level does not improve pet attacks. Accept or complete the matching tamer quest before moving on.\n\n6. Turn in the continent assignment, defeat its grand master and accept the return to the capital. The grand-master introduction is distinct from the later repeatable daily. In Uldum, use Zidormi's earlier phase if needed; in the Vale use the earlier Pandaria phase for Aki, and look inside the Kota Peak cave for Yon. Check the achievement's individual trainer ticks before repeating battles.",
        stepCount = 6,
        waypoints = {
            { mapID = 84, x = 0.6940000000000001, y = 0.244, step = 1, label = "Audrey Burnhep - Alliance pet training" },
            { mapID = 85, x = 0.526, y = 0.593, step = 1, label = "Varzok - Horde pet training" },
            { mapID = 198, x = 0.614, y = 0.32799999999999996, step = 2, label = "Brok" },
            { mapID = 207, x = 0.498, y = 0.57, step = 3, label = "Bordin Steadyfist" },
            { mapID = 241, x = 0.5660000000000001, y = 0.568, step = 4, label = "Goz Banefury" },
            { mapID = 249, x = 0.5660000000000001, y = 0.418, step = 5, label = "Obalis" },
        },
        sources = { "https://www.wowhead.com/achievement=7525#comments:id=1924275" },
        wowheadUrl = "https://www.wowhead.com/achievement=7525",
        sourceURL = "https://www.wowhead.com/achievement=7525#comments",
        reviewedAt = "2026-11-13",
    },
    [7860] = {
        achievementId = 7860,
        name = "We're Going to Need More Saddles",
        source = "We're Going to Need More Saddles",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Collect mounts usable by one character, rather than adding incompatible totals.",
        acquisition = "Difficulty: Medium - Collect mounts usable by one character, rather than adding incompatible totals.\n\n1. Check the achievement's 150-mount counter on a character of the matching faction. Mount Journal's total includes mounts restricted to other factions/classes, so it can exceed the achievement's usable-by-one-character count.\n\n2. Buy missing inexpensive racial mounts and ordinary vendor mounts first. The Pandaren turtle vendors in Stormwind/Orgrimmar and Uncle Bigpocket's basic riding yaks are useful additions if not already learned. Learn the mount items rather than leaving them in bags.\n\n3. Add reputation, quest and legacy-dungeon mounts using their individual acquisition guides. No discontinued promotion or closed arena-season reward is required to reach this total in current Retail.\n\n4. If close to the threshold, log into an eligible paladin or warlock with class mounts and open its Mount Journal so the highest usable total updates. Continue until the actual achievement counter reaches 150, then learn its mailed reward.",
        stepCount = 4,
        waypoints = {
            { mapID = 84, x = 0.6779999999999999, y = 0.18600000000000003, step = 2, label = "Alliance turtle vendor" },
            { mapID = 85, x = 0.698, y = 0.41, step = 2, label = "Horde turtle vendor" },
