    [8302] = {
        achievementId = 8302,
        name = "Mount Parade",
        source = "Mount Parade",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Collect mounts usable by one character, rather than adding incompatible totals.",
        acquisition = "Difficulty: Medium - Collect mounts usable by one character, rather than adding incompatible totals.\n\n1. Check the achievement's 200-mount counter on a character of the matching faction. Mount Journal's total includes mounts restricted to other factions/classes, so it can exceed the achievement's usable-by-one-character count.\n\n2. Buy missing inexpensive racial mounts and ordinary vendor mounts first. The Pandaren turtle vendors in Stormwind/Orgrimmar and Uncle Bigpocket's basic riding yaks are useful additions if not already learned. Learn the mount items rather than leaving them in bags.\n\n3. Add reputation, quest and legacy-dungeon mounts using their individual acquisition guides. No discontinued promotion or closed arena-season reward is required to reach this total in current Retail.\n\n4. If close to the threshold, log into an eligible paladin or warlock with class mounts and open its Mount Journal so the highest usable total updates. Continue until the actual achievement counter reaches 200, then learn its mailed reward.",
        stepCount = 4,
        waypoints = {
            { mapID = 84, x = 0.6779999999999999, y = 0.18600000000000003, step = 2, label = "Alliance turtle vendor" },
            { mapID = 85, x = 0.698, y = 0.41, step = 2, label = "Horde turtle vendor" },
