    [9070] = {
        achievementId = 9070,
        name = "Overstuffed",
        source = "Overstuffed",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Raise an Elekk Plushie yourself; buying it already at 25 does not trigger the level-up.",
        acquisition = "Difficulty: Easy - Raise an Elekk Plushie yourself; buying it already at 25 does not trigger the level-up.\n\n1. Learn an Elekk Plushie from a tailor or a cage BELOW level 25. It has no damaging attacks, so two other pets must carry it through battles if using XP.\n\n2. Use an Ultimate Battle-Training Stone to raise it directly to 25, or use ordinary pet-level stones / safe carry battles to make the final level-up yourself. Taking one from level 24 to 25 is sufficient.\n\n3. Check the achievement when the Plushie reaches 25. Merely buying/learning an already level-25 cage has been reported not to award it. Keep the pet if also working on An Awfully Big Adventure.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 84, 85 },
        sources = {
            "https://www.wowhead.com/achievement=9070",
            "https://www.wowhead.com/achievement=9070#comments:id=2016226",
            "https://www.wowhead.com/achievement=9070#comments:id=2074336",
            "https://www.wowhead.com/achievement=9070#comments:id=2122692",
