            { mapID = 534, x = 0.43, y = 0.358, step = 6, label = "Dazzling Rod - treasure approach" },
            { mapID = 534, x = 0.429, y = 0.353, step = 6, label = "Forgotten Loot - tower top" },
        },
        sources = {
