    [10335] = {
        achievementId = 10335,
        name = "Did Someone Say...?",
        source = "Did Someone Say...?",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Use the obtainable Inflatable Thunderfury consumable.",
        acquisition = "Difficulty: Easy - Use the obtainable Inflatable Thunderfury consumable.\n\n1. Obtain Inflatable Thunderfury from its active anniversary event vendor when offered, or use a saved copy if you already own the consumable. The legendary weapon and its Molten Core bindings are not required for this achievement.\n\n2. Use Inflatable Thunderfury from your bags to display its temporary inflatable weapon and check for the associated achievement credit. Wait for the item cooldown before another attempt if the first use was interrupted.\n\n3. If the anniversary vendor is not active, return during the anniversary event and check its current stock. This seasonal availability belongs under General rather than Draenor questing.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 71 },
        sources = { "https://www.wowhead.com/achievement=10335" },
        sourceURL = "https://www.wowhead.com/achievement=10335#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=10335",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [10354] = {
        achievementId = 10354,
        name = "Crashin' Thrashin' Commander",
        source = "Crashin' Thrashin' Commander",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Learn 200 distinct Toy Box entries across expansions.",
        acquisition = "Difficulty: Medium - Learn 200 distinct Toy Box entries across expansions.\n\n1. Track Crashin' Thrashin' Commander and check the learned-toy count in Collections > Toy Box. Physical duplicates and ordinary usable items without a Toy Box entry do not add unique credit.\n\n2. Use the catalogue's Uncollected filter to collect missing deterministic toys first: faction and reputation vendors you can already access, guaranteed quest rewards and fixed treasures. Learn each item from your bags before counting it.\n\n3. Optional guaranteed pickup - Star Chart: Go to Teluuna Observatory in Shadowmoon Valley, Draenor, at 49.4,37.6. Climb the ramp to the second floor and look on the bed beside the holographic displays, between the draenei NPCs. Loot Astrologer's Box. Horde can walk in without the Alliance story. Alliance characters partway through the Ner'zhul observatory story must finish Shadows Awaken, leave until the purple-fire scenario phase disappears, then return. Pick up any pending profession introductions in your bags if the chest is still phased out. The quest route is a separate optional map entry for that blocked Alliance phase. Skip it if already learned; duplicates add no credit.\n\n4. Optional guaranteed pickup - Pretty Draenor Pearl: Reach the Lagoon Pool on Frostfire Ridge's northwest coast. On foot, take the path down from the Ruins of Ata'gar at 19.0,12.0; with flying, descend directly to the water at 21.8,9.7. Learn Fishing if needed and cast into the glowing pool around the giant clam at 21.8,9.7. Fish up Giant Draenor Clam and open it for the pearl. Swimming down to click the underwater clam does not award it; the treasure's hidden quest is a completion flag, not a quest to accept. Skip it if already learned; duplicates add no credit.\n\n5. Optional guaranteed pickup - Tasty Talador Lunch: Go to the foreman's huts at 57.4,28.7 in northern Talador. The lunchbox is up by the wall above the huts; fly onto the ledge, or climb/jump across the hut roofs. Open Foreman's Lunchbox on the raised ledge. Looking only at ground level below the marker will miss it. Skip it if already learned; duplicates add no credit.\n\n6. Optional guaranteed pickup - Dazzling Rod: Go to Ironhold Harbor in northern Tanaan Jungle and enter the eastern tower at 43.0,35.8. Climb to the top of the tower and open the Forgotten Loot at 42.9,35.3 to obtain the rod. You can also fly to the tower top. Skip it if already learned; duplicates add no credit.\n\n7. Fill remaining gaps with affordable profession toys, dungeon/raid drops and active holiday vendors. Compare each item's real acquisition requirements before paying; retired promotional toys are unnecessary for this threshold.\n\n8. Reach 200 distinct learned entries and check achievement credit. The four mapped guaranteed pickups are optional examples from the existing catalogue, not four additional mandatory criteria.",
        stepCount = 8,
        waypoints = {
            { mapID = 539, x = 0.494, y = 0.376, step = 3, label = "Star Chart - treasure approach" },
            { mapID = 525, x = 0.19, y = 0.12, step = 4, label = "Pretty Draenor Pearl - treasure approach" },
            { mapID = 525, x = 0.218, y = 0.09699999999999999, step = 4, label = "Fish the Lagoon Pool - Giant Draenor Clam" },
            { mapID = 535, x = 0.574, y = 0.287, step = 5, label = "Tasty Talador Lunch - treasure approach" },
            { mapID = 534, x = 0.43, y = 0.358, step = 6, label = "Dazzling Rod - treasure approach" },
            { mapID = 534, x = 0.429, y = 0.353, step = 6, label = "Forgotten Loot - tower top" },
        },
        sources = {
            "https://www.wowhead.com/achievement=10354",
            "https://www.wowhead.com/item=109739#comments",
            "https://www.wowhead.com/item=108739#comments",
            "https://www.wowhead.com/item=116120#comments",
            "https://www.wowhead.com/item=127859#comments",
        },
        sourceURL = "https://www.wowhead.com/achievement=10354#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=10354",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [10355] = {
        achievementId = 10355,
        name = "Lord of the Reins",
        source = "Lord of the Reins",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Build a large collection; cheap vendor sets provide predictable progress.",
        acquisition = "Difficulty: Medium - Build a large collection; cheap vendor sets provide predictable progress.\n\n1. Open the Mounts achievement category and track Lord of the Reins. The requirement is 300 mounts usable by one character, not simply every journal entry visible across both factions and all professions.\n\n2. Collect missing inexpensive racial/vendor sets first. For example visit Mei Francis in Northrend Dalaran for mammoths and bear mounts, or your faction's riding vendors after meeting their purchase requirements. Use each mount item; a refundable item sitting in bags has not added a learned mount.\n\n3. Add deterministic reputation and achievement rewards, then work on dungeon/raid drops you are missing. Check for faction counterparts before paying twice: some pairs unlock together and do not create two usable mounts on the same character.\n\n4. Log into the character with the broadest usable collection, including any relevant class or profession mounts, to refresh the achievement counter. If you are short, compare that character's actual count instead of the account journal's total number of entries.\n\n5. At 300 credited mounts, collect the reward from the achievement delivery/mail and learn Heavenly Azure Cloud Serpent. A separate reputation or riding-training quest for this reward is not required.",
        stepCount = 5,
        waypoints = { { mapID = 125, x = 0.578, y = 0.426, step = 2, label = "Mei Francis - optional collection vendor" } },
        sources = { "https://www.wowhead.com/achievement=10355" },
        sourceURL = "https://www.wowhead.com/achievement=10355#comments",
        wowheadUrl = "https://www.wowhead.com/achievement=10355",
        reviewedAt = "2026-11-15",
        keepReferencePins = true,
        separateQuestMap = true,
        warlordsAchievementGuide = true,
    },
    [10356] = {
        achievementId = 10356,
        name = "Lord of the Reins",
        source = "Lord of the Reins",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Build a large collection; cheap vendor sets provide predictable progress.",
        acquisition = "Difficulty: Medium - Build a large collection; cheap vendor sets provide predictable progress.\n\n1. Open the Mounts achievement category and track Lord of the Reins. The requirement is 300 mounts usable by one character, not simply every journal entry visible across both factions and all professions.\n\n2. Collect missing inexpensive racial/vendor sets first. For example visit Mei Francis in Northrend Dalaran for mammoths and bear mounts, or your faction's riding vendors after meeting their purchase requirements. Use each mount item; a refundable item sitting in bags has not added a learned mount.\n\n3. Add deterministic reputation and achievement rewards, then work on dungeon/raid drops you are missing. Check for faction counterparts before paying twice: some pairs unlock together and do not create two usable mounts on the same character.\n\n4. Log into the character with the broadest usable collection, including any relevant class or profession mounts, to refresh the achievement counter. If you are short, compare that character's actual count instead of the account journal's total number of entries.\n\n5. At 300 credited mounts, collect the reward from the achievement delivery/mail and learn Heavenly Azure Cloud Serpent. A separate reputation or riding-training quest for this reward is not required.",
        stepCount = 5,
        waypoints = { { mapID = 125, x = 0.578, y = 0.426, step = 2, label = "Mei Francis - optional collection vendor" } },
        sources = { "https://www.wowhead.com/achievement=10356" },
        sourceURL = "https://www.wowhead.com/achievement=10356#comments",
