--[====[
Preserved inactive research: Data/General/QuestRoutes.lua
This material is retained for reference and does not register character quest routes.

local _, TDP = ...
local guides = TDP.CollectionWalkthroughs
TDP.CollectionQuestRoutes = TDP.CollectionQuestRoutes or {}
local routes = TDP.CollectionQuestRoutes

-- Retail quest IDs, objectives and pickup locations reviewed 2026-11-12.
-- Route data is immutable; completion and alt snapshots belong to SavedVariables.
-- Every quest has its own Retail source, not a Classic-era level/quest conversion.
local function point(mapID, x, y)
    return { mapID = mapID, x = x / 100, y = y / 100 }
end
local function q(id, name, pickup, instructions, requires, objective, turnIn)
    return { questID = id, name = name, pickup = pickup, instructions = instructions,
        requires = requires, objective = objective, turnIn = turnIn or pickup,
        sourceURL = "https://www.wowhead.com/quest=" .. id }
end
local function route(key, name, quests, options)
    local data = options or {}
    data.key, data.name, data.quests, data.version = key, name, quests, 1
    data.reviewedAt = "2026-11-12"
    routes[key] = data
    return data
end
local function attach(collectionType, ids, additions)
    for _, id in ipairs(ids) do
        local guide = guides[collectionType] and guides[collectionType][id]
        if guide then
            guide.questRoutes = guide.questRoutes or {}
            for _, addition in ipairs(additions) do guide.questRoutes[#guide.questRoutes + 1] = addition end
        end
    end
end

local stv = point(50,44,23.2)
