    q(188,"Tiger Mastery",tiger,"Kill Sin'Dall on her hill and loot her paw. Return to Ajeck for the final tiger turn-in.",{187},point(50,35.8,28.6)),
    q(190,"Panther Hunting",panther,"Sir S. J. Erlgadin: hunt Young Panthers. This branch can be done alongside the tiger and raptor hunts.",{583}),
    q(191,"Panther Stalking",panther,"Hunt Panthers and accept the next field stage when offered.",{190}),
    q(192,"Panther Prowess",panther,"Hunt stealthed Shadowmaw Panthers. Search the highlighted area rather than ordinary young panthers.",{191}),
