    q(195,"Raptor Stalking",raptor,"Hunt Lashtail Raptors and accept the follow-up when it appears.",{194}),
    q(196,"Raptor Prowess",raptor,"Hunt Jungle Stalkers in the quest area.",{195}),
    q(197,"Raptor Mastery",raptor,"Kill Tethis and loot his talon, then return to Hemet Jr.",{196}),
    q(208,"Big Game Hunter",stv,"After all three Mastery turn-ins, kill King Bangalash on the hill, loot his head and turn it in. The old book-page collection is not required.",{188,193,197},point(50,47.5,58.5)),
